CREATE TABLE private_vault (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,name VARCHAR(256) NOT NULL,security_profile VARCHAR(64) NOT NULL,crypto_context TEXT NOT NULL,encrypted_recovery_key TEXT,status VARCHAR(24) NOT NULL DEFAULT 'LOCKED',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,CHECK(security_profile='USER_LOCKED_E2EE'),CHECK(status IN ('LOCKED','UNLOCKED','ARCHIVED')),UNIQUE(owner_id,name)); CREATE TABLE private_notebook (id UUID PRIMARY KEY DEFAULT uuid_v7(),vault_id UUID NOT NULL,owner_id UUID NOT NULL,parent_id UUID,encrypted_name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(vault_id) REFERENCES private_vault(id),FOREIGN KEY(parent_id) REFERENCES private_notebook(id)); CREATE TABLE private_note (id UUID PRIMARY KEY DEFAULT uuid_v7(),vault_id UUID NOT NULL,notebook_id UUID,owner_id UUID NOT NULL,encrypted_title TEXT NOT NULL,encrypted_body TEXT NOT NULL,encrypted_properties TEXT,revision BIGINT NOT NULL DEFAULT 1,tombstone BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(vault_id) REFERENCES private_vault(id),FOREIGN KEY(notebook_id) REFERENCES private_notebook(id)); CREATE INDEX idx_private_note_vault ON private_note(vault_id,owner_id,updated_at DESC);
